{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Vorapaxar, a lipophilic non-ionizable small molecule, has approximately 100% oral bioavailability with no meaningful food effect, supporting high F for the similarly lipophilic, neutral query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Tacrolimus, a macrocyclic lactone natural product with P-gp/CYP3A4 liabilities, still achieves 25% oral bioavailability in liver transplant recipients, indicating that lactone-rich natural products can meet the ≥20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Topiramate, a neutral small molecule with multiple H-bond acceptors, shows >80% oral bioavailability, supporting that the query's polar lactone/ether functionalities do not preclude high absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Theophylline (Uniphyl) under fasting conditions had 53% oral bioavailability, demonstrating that a lipophilic drug can maintain F well above 20% in the fasted state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Amphotericin B has negligible oral bioavailability due to its large polyene structure, poor permeability, low solubility, and acid instability; these features are not shared by the smaller, neutral, lipophilic query, so this low-F evidence has limited transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic, neutral polycyclic lactone (triptolide-like). Most highly transferable experimental evidence shows oral bioavailability at or above 20% for structurally relevant small molecules and lactone natural products, including under fasting conditions. The only strong low-F evidence (amphotericin B) is mechanistically inapplicable. Therefore predict high F (≥20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "Unknown extent of first-pass metabolism and P-glycoprotein efflux for the query.",
    "Fasting-state solubility and absorption not directly assessed for this exact structure.",
    "Human pharmacokinetic data for the query are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

